const body = $input.first().json;
const website = (body.website || '').trim();
if (!website) throw new Error('website is required');
const vendor_name = (body.vendor_name || body.name || '').trim();
const base = website.replace(/\/+$/, '');
return [{ json: { website, vendor_name, admin_url: body.admin_url || '', pricing_url: base + '/pricing' } }];

const input = $input.first().json;
const website = $('Validate Input').first().json.website;
const inputName = $('Validate Input').first().json.vendor_name || '';

// Homepage response
const statusCode = parseInt($('Fetch Homepage').first().json['$response']?.statusCode || input.statusCode || 200);
const html = $('Fetch Homepage').first().json['$response']?.body || input.body || '';

// --- Name extraction helpers ---
function extractMeta(html, property, attr) {
  const re = new RegExp(`<meta[^>]+${attr}=["']${property}["'][^>]+content=["'](.*?)["']`, 'i');
  const m = html.match(re) || html.match(new RegExp(`<meta[^>]+content=["'](.*?)["'][^>]+${attr}=["']${property}["']`, 'i'));
  return m ? m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';
}
function extractTitle(html) {
  const m = html.match(/<title[^>]*>(.*?)<\/title>/is);
  return m ? m[1].replace(/<[^>]+>/g, ' ').replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/\s+/g,' ').trim() : '';
}
function domainStem(url) {
  try {
    const host = new URL(url).hostname.replace(/^www\./, '');
    const base = host.split('.')[0].toLowerCase();
    const prefixes = ['get','try','use','my','the'];
    for (const p of prefixes) {
      if (base.startsWith(p) && base.length - p.length >= 4) {
        return base.slice(p.length).charAt(0).toUpperCase() + base.slice(p.length + 1);
      }
    }
    return base.charAt(0).toUpperCase() + base.slice(1);
  } catch { return ''; }
}
const TAGLINE_SUFFIXES = new Set(['analytics','automation','dashboard','insights','intelligence','management','monitoring','platform','reporting','software','solution','solutions','tracking']);
function isTagline(text) {
  const lower = text.toLowerCase();
  const last = lower.split(/\s+/).pop();
  if (TAGLINE_SUFFIXES.has(last)) return true;
  if (/\bai[- ]powered\b|\b\w+-powered\b|\bpowered by\b/.test(lower)) return true;
  if (/\b\d{4}\b/.test(lower)) return true;
  if (/best |guide|review|how to|top |what is | vs /.test(lower)) return true;
  return false;
}
function cleanCandidate(raw) {
  let s = raw.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  if (!s) return '';
  for (const sep of [' | ',' - ',' \u2013 ',' \u2014 ',': ']) {
    if (s.includes(sep)) {
      for (const part of s.split(sep)) {
        const c = cleanCandidate(part);
        if (c) return c;
      }
    }
  }
  if (isTagline(s)) return '';
  if (s.split(/\s+/).length > 5) return '';
  if (s.length > 40) return '';
  return s;
}

// Priority chain for name
const candidates = [
  extractMeta(html, 'og:site_name', 'property'),
  extractMeta(html, 'application-name', 'name'),
  extractMeta(html, 'apple-mobile-web-app-title', 'name'),
  extractTitle(html),
];
let name = '';
for (const c of candidates) {
  const cleaned = cleanCandidate(c);
  if (cleaned) { name = cleaned; break; }
}
if (!name) {
  const cleaned = cleanCandidate(inputName);
  name = cleaned || domainStem(website);
}

// Homepage text
function htmlToText(h) {
  return h
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
const homepageText = htmlToText(html);

// Pricing page text
const pricingResp = $('Fetch Pricing Page').first()?.json?.['$response'];
const pricingStatus = parseInt(pricingResp?.statusCode || 404);
const pricingHtml = pricingStatus < 400 ? (pricingResp?.body || '') : '';
const pricingText = pricingHtml ? htmlToText(pricingHtml) : '';
const pricing_page_found = pricingText.length > 100;

const combined = homepageText + (pricing_page_found ? '\n\n[PRICING PAGE]\n' + pricingText : '');
const word_count = combined ? combined.split(/\s+/).length : 0;

return [{ json: { website, name, word_count, text: combined.slice(0, 12000), status_code: statusCode, tier_used: 'tier1_direct', ok: statusCode < 400 && word_count > 0, pricing_page_found, pages_fetched: pricing_page_found ? 2 : 1 } }];
